WITH costs AS (
  SELECT r.run_id, h.hold_min, r.onboard_count * h.hold_min + COALESCE((
    SELECT SUM(g.rider_count * ((CASE WHEN g.ready_min <= r.due_min + h.hold_min THEN r.due_min + h.hold_min ELSE r.fallback_min END) - g.ready_min))
    FROM incoming_group AS g WHERE g.run_id = r.run_id
  ), 0) AS passenger_minutes
  FROM outbound_run AS r
  JOIN hold_option AS h ON h.hold_min <= r.slack_min
), ranked AS (
  SELECT costs.*, ROW_NUMBER() OVER (PARTITION BY run_id ORDER BY passenger_minutes, hold_min) AS choice_rank FROM costs
)
SELECT run_id, hold_min, passenger_minutes FROM ranked WHERE choice_rank = 1 ORDER BY run_id;

WITH proposed AS (
  SELECT DISTINCT crate_code, bay_code FROM routing_slip
), disputed AS (
  SELECT crate_code FROM proposed GROUP BY crate_code HAVING COUNT(*) >= 2
), receipts AS (
  SELECT e.crate_code, e.bay_code, e.source_id,
    ROW_NUMBER() OVER (PARTITION BY e.crate_code ORDER BY e.shift_min, e.source_id COLLATE BINARY) AS rn
  FROM dock_evidence AS e JOIN proposed AS p ON p.crate_code = e.crate_code AND p.bay_code = e.bay_code
  WHERE e.event_kind = 'receipt'
)
SELECT d.crate_code, r.bay_code AS accepted_bay, r.source_id
FROM disputed AS d LEFT JOIN receipts AS r ON r.crate_code = d.crate_code AND r.rn = 1
ORDER BY d.crate_code;

WITH records AS (
  SELECT p.line_no,
         CAST(p.line_no AS TEXT) || ',"' || REPLACE(s.replacement, '"', '""') || '","' || REPLACE(s.source_id, '"', '""') || '"' || CHAR(10) AS record
  FROM print_line AS p
  JOIN label_slip AS s ON s.item_code = p.item_code
  WHERE p.current_label COLLATE BINARY IS NOT s.replacement
)
SELECT 'line_no,label,source_id' || CHAR(10) || COALESCE((
  SELECT GROUP_CONCAT(record, '') FROM (SELECT record FROM records ORDER BY line_no ASC)
), '') AS csv_body;
